        break;
      case "eventChoice": {
        const c = events.find((e) => e.id === s.event).choices[a.index];
        if (a.tradeItem != null) {
          const offered = this.getItem(a.tradeItem);
          this.log(
            `Traded ${items[offered.id].name} (item ${offered.uid})${offered.gem ? "; socketed Gem returned to Satchel" : ""}.`,
          );
          this.removeItem(a.tradeItem);
        }
        if (a.tradeCard != null) {
          const offered = s.deck.find((x) => x.uid === a.tradeCard);
          this.log(
            `Traded ${cards[offered.id].name}${offered.upgrade ? " +" : ""} (card ${offered.uid}).`,
          );
          s.deck = s.deck.filter((x) => x.uid !== a.tradeCard);
        }
        if (c.cost) this.spend(c.cost);
        if (c.hp) {
          s.hp += c.hp;
          s.stats.damageTaken += Math.max(0, -c.hp);
        }
        if (c.heal) s.hp = Math.min(s.maxHp, s.hp + c.heal);
        if (c.gold) this.gainGold(c.gold);
        if (c.card) this.addCard(c.card);
        if (c.hex) this.addCard(c.hex);
        if (c.item) this.addItem(c.item);
        if (c.quest) s.quest = true;
        if (c.clean || c.cleanHex)
          s.deck = s.deck.filter((x) => cards[x.id].type !== "Hex");
        if (c.clean)
          for (const x of [...s.inventory])
            if (items[x.id].cursed) this.removeItem(x.uid);
        if (s.hp <= 0)
          this.finish(false, events.find((e) => e.id === s.event).name);
        else if (c.fight)
          this.beginBattle([{ uid: this.uid(), enemy: c.fight, restless: 0 }]);
        else this.resolveTile();
        break;
      }
      case "rewardCard":
        this.addCard(a.id);
        s.reward.cards = null;
        break;
      case "skipReward":
        s.reward.cards = null;
        break;
      case "rewardGem":
        this.addItem(a.id);
        s.reward.gem = false;
        break;
      case "rewardSetting":
        this.addItem(a.id);
        s.reward.setting = false;
        break;
      case "continueReward":
        if (s.reward.boss && !s.tutorial && (s.stratum || 1) === 1) this.enterStratum2();
        else if (s.reward.boss) this.finish(true);
        else this.resolveTile();
        break;
      case "leave":
        if (s.loomIntro) { s.mode = "loomIntro"; }
        else this.resolveTile();
        break;
      case "heal":
        this.spend(20);
        s.hp = Math.min(s.maxHp, s.hp + 20);
        s.shop.healUsed = true;
        break;
      case "gossip":
        this.spend(15);
        s.revealedArchon = s.archon;
        s.shop.gossipUsed = true;
        s.nextTavernHealer = this.rand() < 0.75;
        s.nextHealerHint = s.nextTavernHealer;
        this.log(
          s.nextHealerHint
            ? "A healer will visit the next Tavern."
            : "No healer will visit the next Tavern.",
        );
        this.log("The traveler names " + enemies[s.archon].name + ".");
        break;
      case "buy": {
        const id = s.shop.stock.splice(a.index, 1)[0];
        this.spend(a.price);
        s.stats.purchases.push(id);
        if (id.startsWith("card:")) this.addCard(id.slice(5));
        else this.addItem(id);
        break;
      }
      case "sell": {
        const item = this.getItem(a.uid);
        if (items[item.id].cursed) this.spend(a.value);
        else this.gainGold(a.value);
        s.stats.sales.push(item.id);
        this.removeItem(a.uid);
        break;
      }
      case "socket":
        this.getItem(a.uid).gem = a.gem;
        break;
      case "unsocket":
        this.getItem(a.uid).gem = null;
        break;
      case "remove":
        this.spend(40);
        s.shop.removeUsed = true;
        s.deck = s.deck.filter((x) => x.uid !== a.uid);
        break;
      case "removeHex":
        if (a.costs.gold) this.spend(a.costs.gold);
        if (a.costs.hp) {
          s.hp -= a.costs.hp;
          s.stats.damageTaken += a.costs.hp;
        }
        s.deck = s.deck.filter(
          (x) => x.uid !== a.uid && x.uid !== a.sacrificeCard,
        );
        if (a.sacrificeItem) this.removeItem(a.sacrificeItem);
        this.log(a.label);
        break;
      case "upgrade": {
        const c = s.deck.find((x) => x.uid === a.uid),
          u = cards[c.id].upgrade;
        if (u.gold) this.spend(u.gold);
        if (u.hp) {
          s.hp -= u.hp;
          s.stats.damageTaken += u.hp;
        }
        if (a.sacrifice) s.deck = s.deck.filter((x) => x.uid !== a.sacrifice);
        c.upgrade = true;
        break;
      }
      case "enterLoom":
        delete s.loomIntro;
        this.beginRound();
        break;
      case "place": {
        const c = b.hand.find((x) => x.uid === a.uid),
          d = cards[c.id];
        b.hand = b.hand.filter((x) => x.uid !== a.uid);
        b.focus -= a.costs.focus;
        b.milky = false;
        const slot = b.grid[a.slot];
        if (d.stack === "recall" && slot.length) {
          for (let i = slot.length - 1; i >= 0; i--)
            if (cards[slot[i].id].recall != null && !slot[i].lock)
              b.discard.push(
                ...slot
                  .splice(i, 1)
                  .map((x) => ({ uid: x.uid, id: x.id, upgrade: x.upgrade })),
              );
        }
        const inst = this.instance(c);
        slot.push(inst);
        if (
          d.bondHP &&
          this.neighbors(a.slot).some((j) => top(b.grid[j]).element === "Earth")
        )
          inst.hp += d.bondHP;
        inst.maxHp = Math.max(inst.maxHp, inst.hp);
        capAllyHP(inst);
        if (d.onPlaceCharge)
          inst.charge = Math.min(
            d.charge,
            this.neighbors(a.slot).filter(
              (j) => top(b.grid[j]).element === "Fire",
            ).length,
          );
        if (d.onPlaceFocus) b.focus += d.onPlaceFocus;
        break;
      }
      case "recall":
        b.focus -= a.costs.focus;
        b.discard.push(
          ...b.grid[a.slot].map((c) => ({
            uid: c.uid,
            id: c.id,
            upgrade: c.upgrade,
          })),
        );
        b.grid[a.slot] = [];
        break;
      case "activatePhase":
        b.discard.push(...b.hand);
        b.hand = [];
        b.phase = "activate";
        break;
      case "activate":
        this.activate(a);
        break;
      case "endTurn":
        this.endTurn();
        break;
      case "ward": {
        const c = b.grid[a.slot].find((c) => c.uid === a.uid),
          h = b.reaction;
        const loss = Math.min(c.ward, h.damage);
        c.ward -= loss;
        h.damage -= loss;
        h.weaknessBonus = 0;
        h.weaknessElement = null;
        if (!c.ward) c.zeroWard = true;
        this.presentIncomingNode(
          "defend",
          { slot: a.slot, amount: loss, loss, name: "Ward absorbs" },
          { kind: "card", slot: a.slot },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "block":
      case "bracelet": {
        const p = (a.type === "block" ? b.shields : b.bracelets).find(
          (x) => x.uid === a.uid,
        );
        b.reaction.weaknessBonus = 0;
        b.reaction.weaknessElement = null;
        const r = blockHit(
          p.block,
          p.element,
          b.reaction.damage,
          b.reaction.element,
        );
        const stopped = b.reaction.damage - r.remaining;
        const loss = p.block - r.block;
        p.block = r.block;
        b.reaction.damage = r.remaining;
        this.presentIncomingNode(
          "defend",
          {
            slot: a.type === "block" ? p.slot : null,
            item: a.type === "bracelet" ? a.uid : null,
            amount: stopped,
            loss,
            name: "Absorbed",
          },
          a.type === "block"
            ? { kind: "card", slot: p.slot }
            : { kind: "item", uid: a.uid },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "armor": {
        const h = b.reaction;
        const armor = this.defenseChoices().armors.find((x) => x.uid === a.uid);
        let loss;
        h.weaknessBonus = 0;
        h.weaknessElement = null;
        const result = armor.reflect
          ? { remaining: 0, block: b.armorBlock }
          : blockHit(b.armorBlock, armor.element, h.damage, h.element);
        const stopped = h.damage - result.remaining;
        loss = armor.reflect ? stopped : b.armorBlock - result.block;
        b.armorBlock = result.block;
        if (armor.reflect) {
          b.mirror = true;
          const enemy = b.enemies.find((e) => e.uid === h.source);
          if (enemy) {
            enemy.hp -= stopped;
            s.stats.damageDealt += stopped;
          }
        }
        h.damage -= stopped;
        this.presentIncomingNode(
          "defend",
          {
            item: a.uid,
            amount: stopped,
            loss,
            name: armor.reflect ? "Reflected" : "Armor protects",
          },
          { kind: "item", uid: a.uid },
        );
        this.advanceHit();
        this.pump();
        break;
      }
      case "intercept":
        this.intercept(a.slot);
        this.pump();
        break;
      case "skipEquipment":
        this.log("You let the hit through without using remaining defenses.");
        b.reaction.stage = "player";
        this.advanceHit();
        this.pump();
        break;
      case "takeHit":
        b.reaction.column = -1;
        b.reaction.stage = "bracelet";
        this.advanceHit();
        this.pump();
        break;
    }
    if (
      s.pendingPickupResolution &&
      satchelContents(s).length <= SATCHEL_CAPACITY
    ) {
      delete s.pendingPickupResolution;
      this.resolveTile();
    }
    if (b) resetCoveredInsanity(b);
    const challenge = s.stats.withoutMenders;
    if (challenge && !challenge.disqualified) {
      if (!s.deck.some(c=>c.uid===challenge.uid)) challenge.disqualified = "companion removed";
      if ((a.type==="place" && b?.grid[a.slot]?.some(c=>c.id==="elves")) || (a.type==="activate" && b?.grid[a.slot]?.some(c=>c.id==="elves"))) challenge.disqualified = "Machine Elves used";
    }
    tutorialAfter(this, a);
    return this.observe();
  }
  removeItem(uid) {
    const s = this.s;
    for (const k of Object.keys(s.equipment))
      if (s.equipment[k] === uid) s.equipment[k] = null;
    for (const x of s.inventory) if (x.gem === uid) x.gem = null;
    s.inventory = s.inventory.filter((x) => x.uid !== uid);
  }
  observe() {
    const s = this.s;
    const o = {
      version: VERSION,
      stratum: s.stratum || 1,
      stratumName: STRATA[s.stratum || 1].name,
      loomIntro: s.loomIntro,
      tutorial: s.tutorial
        ? {
            id: s.tutorial.id,
            version: s.tutorial.version,
            name: s.tutorial.name,
            completed: s.tutorial.completed,
            fight: s.tutorial.fight,
            step: s.tutorial.step,
            lesson: s.tutorial.lesson,
            guide: tutorialGuide(this),
          }
        : null,
      mode: s.mode,
      classId: s.classId,
      hp: Math.max(0, s.hp),
      maxHp: s.maxHp,
      gold: s.gold,
      deck: clone(s.deck),
      inventory: clone(s.inventory),
      satchel: { used: satchelContents(s).length, capacity: SATCHEL_CAPACITY },
      equipment: clone(s.equipment),
      bonuses: this.bonuses(),
      status: clone(s.status),
      field: clone(s.field),
      log: s.log.slice(-30),
      steps: s.steps,
      stats: clone(s.stats),
      startGem: s.startGem,
      archon: s.revealedArchon ? enemies[s.revealedArchon].name : null,
      pendingArmor: s.pendingArmor,
      nextHealerHint: s.nextHealerHint,
    };
    if (s.mode === "battle") {
      o.battle = clone(s.battle);
      delete o.battle.jobs;
      o.battle.telegraphs = this.gridTelegraphs();
      o.battle.deck.sort((a, b) => a.id.localeCompare(b.id) || a.uid - b.uid);
      o.battle.enemies = o.battle.enemies
        .filter((e) => e.hp > 0 || (enemies[e.id].onDeath && !e.deathResolved))
        .map((e) => ({
          ...e,
          hp: Math.max(0, e.hp),
          statusImmunity: enemyStatusImmunity(e),
          statusImmunities: enemyStatusImmunities(e),
          signature:
            enemies[e.id].signature +
            (enemyStatusImmunity(e)
              ? ` Immune to ${statusName(enemyStatusImmunity(e))} while ${e.element}.`
              : ""),
          counter: enemies[e.id].counter,
          rotation: enemies[e.id].rotation.map((t) => ({
            ...clone(t),
            ...(t.currentElement ? { element: e.element } : {}),
          })),
          onDeath: clone(enemies[e.id].onDeath),
          tell: e.hp <= 0 ? clone(enemies[e.id].onDeath) : this.tell(e),
        }));
    }
    if (s.mode === "event") o.event = events.find((e) => e.id === s.event);
    if (s.mode === "tavern") o.shop = clone(s.shop);
    if (s.mode === "item") o.itemOffer = clone(s.itemOffer);
    if (s.mode === "reward") o.reward = clone(s.reward);
    if (s.mode === "result") {
      o.outcome = s.outcome;
      o.cause = s.cause;
      o.death = clone(s.death);
      o.seed = s.seed;
      o.history = clone(s.history);
    }
    return o;
  }
  save() {
    return clone(
      this.s.mode === "battle" && this.s.checkpoint && !this.s.tutorial
        ? this.s.checkpoint
        : this.s,
    );
  }
}

sources.strata.mjs:
export const STRATA = {
  1: { name: "The Whispering Weald", early: ["bat", "beetle", "moth", "wisp"] },
  2: { name: "The Unfinished Loom", early: ["sourcap", "loopMoth", "dewThief", "threadMite"] },
};
export const ELVES_STORY = "The path ends at a tear in the ground. Three small figures kneel beside it, passing a silver thread through places your eyes cannot follow. One pulls; the far bank draws close. They pack their needles when they see you. The smallest points at your grimoire, then at the damaged path ahead. You open the book. They climb inside.";
export const CORRUPTIONS = {
  hole: { name: "Memory Hole", symbol: "◉", advanced: true, text: "This space cannot accept cards. Upgraded Machine Elves are the exception: place them here and Mend to repair it." },
  nausea: { name: "Nausea", symbol: "≈", text: "While uncovered, orthogonally adjacent cards deal half damage and generate half Guard (rounded down). Multiple Nauseas do not multiply. Cover this space to suppress it; the Corruption remains underneath." },
  insanity: { name: "Insanity", symbol: "↻", text: "At the start of each player turn while uncovered, lose 1, then 2, then 3 HP, and so on. Cover to suppress and reset to 1. This bypasses defenses." },
  mine: { name: "Mind Mine", symbol: "✹", advanced: true, text: "Explodes after three full player turns. Uncovered: 18 Arcane damage through the normal defense chain. Covered: destroys only the top card instead. Covering does not pause the fuse." },
  hypnosis: { name: "Hypnosis", symbol: "◎", advanced: true, text: "At the end of the enemy round, the top card spends one remaining use: its damage attacks you, or its Guard protects the source enemy. No Channel cost. Charging cards gain a charge instead. Once-per-turn activation still applies. Machine Elves and utility-only cards cannot be compelled." },
};

export function registerStratum2(card, enemy, glossary) {
  card("elves", "Machine Elves", "Arcane", "Ally", 1, 1, { mend: true }, "Mend: repair the Corruption beneath this card at the start of your next turn, then return to discard. Must survive. Repairs Nausea and Insanity; upgraded, also Memory Hole, Mind Mine and Hypnosis. Place only on a repairable Corruption.", { stratum: 2, companion: true, hp: 4, upgrade: { gold: 100, text: "Also repairs Memory Hole, Mind Mine and Hypnosis. Can enter Memory Holes." } });
  card("quietStitch", "Quiet Stitch", "Water", "Spell", 1, 1, { stitch: true }, "Remove Nausea or Insanity from this space immediately. Single use; Destroyed after activation.", { stratum: 2, rarity: "common", destroyAfterActivation: true, singleUse: true, recall: null });
  const hit = (name, damage, element, extra = {}) => ({ name, damage, element, ...extra });
  const rest = { name: "Gather the threads", element: "Arcane" };
  const mark = (kind, count = 1) => ({ name: "Foretell " + CORRUPTIONS[kind].name, element: "Arcane", markCorruption: kind, count });
  const apply = (kind) => ({ name: CORRUPTIONS[kind].name, element: "Arcane", applyCorruption: true });
  const add = (id, name, tier, element, hp, movement, rotation, signature, counter, extra = {}) => enemy(id, name, tier, element, hp, movement, rotation, signature, counter, { stratum: 2, ...extra });
  add("sourcap", "Sourcap Tender", "Mote", "Earth", 28, "Stalker", [hit("Spore tap",5,"Earth"),mark("nausea"),apply("nausea"),hit("Root lash",7,"Earth")], "Telegraphs one Nausea space; covering it restores neighboring cards' power.", "Cover the marked space, or keep your attacks away from its neighbors.", { corruptionCap: 1 });
  add("loopMoth", "Loop Moth", "Mote", "Wind", 25, "Skittish", [hit("Frayed wing",6,"Wind"),mark("insanity"),apply("insanity"),rest], "Telegraphs one Insanity space, which hurts while uncovered.", "A cheap cover stops the escalating loss.", { corruptionCap: 1 });
  add("dewThief", "Dew Thief", "Mote", "Water", 30, "Skittish", [hit("Dew needle",6,"Water"),{name:"Glass dew",guard:6,element:"Water"},rest], "Steals a quiet turn to gather 6 Guard.", "Build during the pause, then strike with Wind.");
  add("threadMite", "Thread Mite", "Mote", "Arcane", 20, "Stalker", [hit("Snip",4,"Arcane"),{name:"Tangle",channel:-1,element:"Arcane"},rest], "Tangle removes one Channel next turn only.", "Use its quiet rounds to place cards.", {grouped:true});
  add("frayedHound", "Frayed Hound", "Mote", "Fire", 40, "Hunter", [hit("Twin fangs",5,"Fire",{hits:2}),{name:"Distraction",focus:-1,element:"Fire"},hit("Bound",9,"Fire")], "Two Fire bites, then a Focus tax and one heavy attack.", "Water defenses handle the bites; develop during Distraction.");
  add("hollowScribe", "Hollow Scribe", "Mote", "Light", 34, "Sentinel", [mark("hole"),apply("hole"),hit("Unwrite",8,"Light"),rest], "Telegraphs one Memory Hole on an empty space.", "Occupying its mark before it resolves prevents the Hole.", {corruptionCap:1});
  add("bellowsGrub", "Bellows Grub", "Mote", "Fire", 38, "Stalker", [{name:"Draw breath",element:"Fire"},hit("Exhale",10,"Fire"),rest], "A heavy breath with two turns between attacks.", "Prepare Water Guard while it inhales.");
  add("looseEcho", "Loose Echo", "Mote", "Chaos", 32, "Stalker", [hit("First echo",7,"Chaos"),hit("Answer",7,"Light"),rest], "Alternates Chaos and Light attacks before a pause.", "Read each Tell; neutral defense avoids mutual weaknesses.");
  add("spoolkeeper", "Spoolkeeper", "Eidolon", "Arcane", 85, "Stalker", [hit("Spindle",8,"Arcane"),mark("nausea",2),apply("nausea"),hit("Double stitch",6,"Arcane",{hits:2}),rest], "Two Nausea spaces disrupt formations. Maximum two active Corruptions.", "Spread your damage, or cover the sick spaces.", {corruptionCap:2});
  add("borrowedFace", "Borrowed Face", "Eidolon", "Water", 80, "Hunter", [mark("insanity"),apply("insanity"),hit("Borrowed smile",9,"Water"),{name:"Mirror skin",guard:8,element:"Water"},hit("Tear",9,"Water")], "Adds Insanity while sheltering behind Guard. Maximum two.", "Cover early; Wind cuts through its defenses.", {corruptionCap:2});
  add("surveyor", "Quiet Surveyor", "Eidolon", "Earth", 90, "Sentinel", [mark("hole"),apply("hole"),hit("Measure twice",7,"Earth",{hits:2}),rest], "Telegraphs empty spaces for Memory Holes. Maximum two.", "Occupy its marks, route around holes, or upgrade the Elves.", {corruptionCap:2});
  add("seamstress", "Seamstress of Absence", "Archon", "Light", 190, "Archon", [hit("Silver needles",8,"Light",{hits:2}),{...mark("hole"),alsoCorruption:"nausea"},apply("hole"),hit("Cut the seam",12,"Light"),{name:"Fold inward",guard:10,element:"Light"}], "Unthreads empty spaces into Memory Holes beside a Nausea mark. Maximum three active Corruptions.", "Fill a Hole mark before it resolves. Cover Nausea; preserve a flexible formation.", {corruptionCap:3,bossMode:"stalker"});
  add("censer", "Censer Engine", "Archon", "Fire", 210, "Archon", [hit("Furnace breath",9,"Fire"),mark("mine"),apply("mine"),hit("Bellows",6,"Fire",{hits:2}),rest], "Plants telegraphed Mind Mines with three full response turns. Maximum two. An uncovered explosion deals 18 Arcane; a cover sacrifices its top card.", "Use spent cards as covers, or repair early with upgraded Elves.", {corruptionCap:2,bossMode:"stalker"});
  add("borrowedChoir", "Choir of Borrowed Hands", "Archon", "Chaos", 180, "Archon", [hit("Invitation",8,"Chaos"),mark("hypnosis"),apply("hypnosis"),hit("Marionette hymn",10,"Chaos"),{name:"Release the strings",releaseCorruption:true,element:"Chaos"}], "Hypnosis compels a marked attack or defense card on enemy turns, spending its normal uses. Releases its Corruption at cycle end.", "Activate the marked card first, Recall it, or let its allowance run out. Repair with upgraded Elves.", {corruptionCap:1,bossMode:"hunter"});
  add("mendingTutor", "Patient Spool", "Mote", "Arcane", 100, "Sentinel", [rest], "A patient presence at the Mending Ground.", "Learn how spaces remember.", {tutorialOnly:true});
  add("mendingWarden", "Patient Spoolkeeper", "Eidolon", "Arcane", 40, "Sentinel", [rest,hit("Loose spindle",5,"Arcane"),mark("nausea"),apply("nausea"),rest], "A gentle final practice: one Nausea space, with pauses between attacks.", "Cover the space or Mend; keep an attack ready.", {tutorialOnly:true,corruptionCap:1});
  for (const def of Object.values(CORRUPTIONS)) glossary[def.name] = def.text;
  glossary.Mend = "Machine Elves spend one activation, survive through the enemy round, then repair their space and return to discard at the next player turn. Freeze delays completion.";
}

sources.corruptions.mjs:
import { cards } from "./content.mjs";
import { CORRUPTIONS } from "./strata.mjs";
const top = (stack) => stack.at(-1);
const neighbors = (i) => [i % 7 ? i-1 : -1, i % 7 < 6 ? i+1 : -1, i-7, i+7].filter(j => j >= 0 && j < 42);
export function corruptionAt(b, i) { return b.corruptions?.[i] || null; }
export function canMend(c, corruption) { return !!corruption && (c.upgrade || !CORRUPTIONS[corruption.kind].advanced); }
export function canEnter(b, c, i) {
  const q = corruptionAt(b, i);
  if (top(b.grid[i])?.mending) return false;
  if (c.id === "elves") return !b.grid[i].length && canMend(c, q);
  return q?.kind !== "hole";
}
export function corruptionPower(b, i, power) {
  return neighbors(i).some(j => corruptionAt(b,j)?.kind === "nausea" && !b.grid[j].length)
    ? Math.floor(power / 2) : power;
}
export function resetCoveredInsanity(b) {
  for (const [i,q] of Object.entries(b.corruptions || {}))
    if (q.kind === "insanity" && b.grid[i].length) q.value = 1;
}
export function prepareCorruption(g, e, t) {
  const b = g.s.battle;
  b.corruptions ||= {};
  const existing = Object.values(b.corruptions).filter(q => q.source === e.uid).length;
  let room = (e.corruptionCap || 1) - existing;
  e.corruptionPlan = [];
  const kinds = [...Array(t.count || 1).fill(t.markCorruption), ...(t.alsoCorruption ? [t.alsoCorruption] : [])];
  for (const kind of kinds) {
    if (room-- <= 0) break;
    let candidates = b.grid.flatMap((stack,i) => {
      if (b.corruptions[i] || e.corruptionPlan.some(p=>p.slot===i)) return [];
      const c = top(stack), d = cards[c?.id], f = d?.effects;
      if (kind === "hole" && stack.length) return [];
      if (kind === "hypnosis" && (!c || !(f.damage || f.hpDamage || f.shield || f.ward || f.randomDamage))) return [];
      return [i];
    });
    if (!candidates.length) continue;
    // Seeded, committed space. Never follow a recalled/moved card.
    const slot = g.pick(candidates);
    e.corruptionPlan.push({slot,kind});
    g.log(e.name + " marks " + CORRUPTIONS[kind].name + " at row " + (Math.floor(slot/7)+1) + ", column " + (slot%7+1) + ". One player turn to respond.");
    g.present("corruption", {slot, name:"Foretold: " + CORRUPTIONS[kind].name});
  }
}
export function applyCorruptions(g,e) {
  const b = g.s.battle;
  for (const {slot,kind} of e.corruptionPlan || []) {
    if (b.corruptions[slot] || (kind === "hole" && b.grid[slot].length)) {
      g.log(CORRUPTIONS[kind].name + " fails at its committed space.");
      continue;
    }
    b.corruptions[slot] = {kind,uid:g.uid(),source:e.uid,value:1,remaining:3,createdTurn:b.turn};
    g.log(CORRUPTIONS[kind].name + " corrupts a space.");
    g.present("corruption",{slot,name:CORRUPTIONS[kind].name});
  }
  e.corruptionPlan = [];
  resetCoveredInsanity(b);
}
export function startRepairs(g) {
  const b=g.s.battle;
  for (const [i,stack] of b.grid.entries()) {
    const c=top(stack), m=c?.mending;
    if (!m || m.due>b.turn || c.freeze>=b.turn) continue;
    const q=corruptionAt(b,i);
    if (m.slot!==i || (q && q.uid!==m.corruptionUid)) { delete c.mending; continue; }
    delete b.corruptions[i];
    stack.pop();
    b.discard.push({id:c.id,uid:c.uid,upgrade:c.upgrade});
    (g.s.stats.repairs ||= []).push({stratum:g.s.stratum,turn:b.turn,slot:i,kind:m.kind,card:c.uid});
    g.present("corruption",{slot:i,name:"Mended · Elves return to discard"});
    g.log("Machine Elves mend " + CORRUPTIONS[m.kind].name + " and return to discard.");
  }
  resetCoveredInsanity(b);
  for (const [i,q] of Object.entries(b.corruptions || {})) {
    if(q.kind!=="insanity" || b.grid[i].length) continue;
    const loss=Math.min(g.s.hp,q.value++);
    g.s.hp-=loss;g.s.stats.damageTaken+=loss;
    g.present("hit",{target:"player",amount:loss,element:"Chaos",name:"Insanity"});
    g.log("Insanity: lose " + loss + " HP.");
    if(g.s.hp<=0) {g.finish(false,"Insanity");return;}
  }
}
export function corruptionRound(g) {
  const b=g.s.battle;
  resetCoveredInsanity(b);
  for(const [key,q] of Object.entries(b.corruptions || {})) {
    const i=Number(key),c=top(b.grid[i]);
    if(q.kind === "mine" && q.createdTurn < b.turn && --q.remaining<=0) {
      delete b.corruptions[i];
      g.present("corruption",{slot:i,name:"Mind Mine detonates"});
      if(c) {g.destroyCard(i,c.uid);g.log("Mind Mine destroys its cover.");}
      else b.jobs.unshift({kind:"hit",name:"Mind Mine",damage:18,element:"Arcane",gridSourceSlot:i,source:q.source});
    }
    if(q.kind!=="hypnosis" || !c || !g.activationAvailable(c,i) || !g.condition(c,i)) continue;
    const d=cards[c.id],f=d.effects,source=b.enemies.find(e=>e.uid===q.source && e.hp>0);
    if(!source || !(f.damage || f.hpDamage || f.randomDamage || f.shield || f.ward)) continue;
    c.used++;c.lastActivatedTurn=b.turn;
    g.present("corruption",{slot:i,name:"Hypnosis · " + d.name});
    if(d.charge && c.charge<d.charge) {c.charge=Math.min(d.charge,c.charge+1);continue;}
    if(d.charge)c.charge=0;
    const damage=f.randomDamage ? corruptionPower(b,i,1+Math.floor(g.rand()*f.randomDamage)) : g.cardPower(c,i);
    if(damage) b.jobs.unshift({kind:"hit",name:"Hypnosis · " + d.name,damage,element:c.lastActivationElement || c.element,source:q.source,gridSourceSlot:i});
    if(f.shield || f.ward)source.guard+=f.shield ? g.shieldPower(c,i) : corruptionPower(b,i,f.ward+(c.upgrade ? d.upgrade?.bonus||0 :0));
    if(d.destroyAfterActivation)g.destroyCard(i,c.uid);
  }
}

sources.policy.mjs:
import { cards, items, enemies, VERSION } from "./content.mjs";
import {
  activationGrowth,
  defensiveElement,
  offense,
  defenseRate,
  adjacent,
  allyHit,
  corner,
  enemyImmuneTo,
} from "./engine.mjs";
export const defaultWeights = {
  damage: 1,
  survival: 1.4,
  economy: 4,
  development: 1,
  progress: 1,
};
const dist = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
export class WeightedPolicy {
  constructor(weights = {}) {
    this.weights = { ...defaultWeights, ...weights };
    this.id = "weighted-druid-v2.0";
  }
  choose(o, actions) {
    if (!actions.length) return null;
    let winner = actions[0],
      best = -Infinity,
      reason = "Use an available legal choice.";
    for (const a of actions) {
      let score = -0.01,
        why = "Fallback for a legal choice with unfamiliar effects.";
      try {
        [score, why] = this.score(o, a);
        const b=o.battle, q=b?.corruptions?.[a.slot];
        if (a.type==="place" && b) {
          const card=b.hand.find(c=>c.uid===a.uid), d=cards[card?.id];
          if(q?.kind==="insanity" || q?.kind==="nausea") score+=q.kind==="insanity" ? 14 : 7;
          if(card?.id==="elves") score+=9;
          if(q?.kind==="mine") score+=q.remaining<=1 ? (d?.focus===0 || card?.id==="shield" ? 18 : -8) : 2;
          if(q?.kind==="hypnosis" && (d?.effects.damage || d?.effects.shield || d?.effects.ward))score-=12;
          if(b.enemies.some(e=>e.corruptionPlan?.some(p=>p.slot===a.slot && p.kind==="hole")))score+=10;
        }
        if(a.type==="activate" && (a.effects.mend || a.effects.stitch)) {score+=18;why="Repair the corrupted space while protecting the companion.";}
        if(a.type==="recall" && q && ["nausea","insanity","mine"].includes(q.kind))score-=20;
        if(a.type==="activate" && q?.kind==="hypnosis")score+=8;
        if (!Number.isFinite(score)) score = -0.01;
      } catch {}
      if (score > best) {
        best = score;
        winner = a;
        reason = why;
      }
    }
    return { action: winner, reason, score: best, policy: this.id };
  }
  cardValue(id, o) {
    const d = cards[id];
    if (!d) return 0;
    const e = d.effects;
    return (
      (e.damage || 0) / (d.charge ? d.charge + 1 : 1) +
      (d.hp || 0) * 0.6 +
      (e.ward || 0) * 0.55 +
      (e.shield || 0) * 0.4 +
      (e.channel || 0) * 6 +
      ((e.insight || 0) + 2 * (e.adjInsight || 0)) * 1.5 +
      (e.focusPermanent || 0) * 10 +
      (e.heal || 0) * 1.5 +
      (e.poison || 0) * 3 +
      (e.burn || 0) * 2 +
      (e.corrode || 0) * 6 +
      (e.hpDamage ? 8 : 0) +
      (d.growth ? 8 : e.growAfterAttack ? 4 : 0) +
      (e.conduit ? 4 : 0) -
      (d.focus - 1) * 3 -
      (d.type === "Hex" ? 40 : 0)
    );
  }
  gearValue(e = {}, o) {
    return (
      (e.channel || 0) * 20 +
      (e.focus || 0) * 14 +
      (e.insight || 0) * 6 +
      (e.block || 0) * 2 +
      (e.heal || 0) * 6 +
      (e.armor || 0) * 6 +
      (e.damage || 0) * (e.firstAttackOnly ? 3 : 4.5) +
      (e.movement || 0) * 3 +
      (e.resist ? 4 : 0) +
      (e.reflect ? 12 : 0) +
      (e.shield || 0) *
        (!o || o.deck.some((c) => cards[c.id]?.name.includes("Shield"))
          ? 4
          : 0) +
      (e.recall || 0) * 3 -
      (e.burn || 0) * 3 -
      (e.poison || 0) * 6 -
      (e.corrode || 0) * 12
    );
  }
  // Compare the actual owned instance, including benefits lost with its socket.
  // Elemental attunement is matchup-dependent, not an unconditional upgrade.
  itemValue(inst, o) {
    const d = items[inst?.id];
    if (!d) return 0;
    if (d.consumable)
      return (
        (d.consumable.heal || 0) * 0.8 +
        (d.consumable.focus || 0) * 6 +
        (d.consumable.channel || 0) * 8 +
        (d.consumable.draw || 0) * 4 +
        (d.consumable.damage || 0) * 0.8
      );
    const gem = items[o.inventory.find((x) => x.uid === inst.gem)?.id];
    return (
      this.gearValue(d.effect, o) -
      (d.cursed ? 40 : 0) +
      (gem
        ? this.gearValue(
            gem.id === "curseGem" ? { ...gem.effect, poison: 0 } : gem.effect,
            o,
          )
        : 0) +
      (gem && d.synergy === gem.id ? this.gearValue({ heal: 1 }, o) : 0)
    );
  }
  score(o, a) {
    const f = a.effects || {},
      w = this.weights,
      b = o.battle,
      injured = o.maxHp - o.hp;
    let n = 0,
      reason = a.label;
    switch (a.type) {
      case "discardItem":
        return [
          -30 -
            this.itemValue(
              o.inventory.find((x) => x.uid === a.uid),
              o,
            ),
          "Make Satchel space by discarding the least valuable loose item.",
        ];
      case "consume": {
        const reserve = 5;
        if (f.heal)
          return [
            Math.min(injured, f.heal) * w.survival - reserve,
            "Use finite healing when enough HP is missing.",
          ];
        if (f.focus) {
          const useful = b.hand.some(
            (c) =>
              cards[c.id].focus > b.focus &&
              cards[c.id].focus <= b.focus + f.focus,
          );
          return [
            useful ? 8 : -20,
            "Spend a Focus Draught only when it unlocks a placement.",
          ];
        }
        if (f.channel)
          return [
            b.channel === 0 &&
            b.grid.some((slot, i) => {
              const c = slot.at(-1);
              return (
                c &&
                c.used < cards[c.id].limit &&
                c.lastActivatedTurn !== b.turn
              );
            })
              ? 8
              : -20,
            "Restore Channel when an unused card can benefit.",
          ];
        if (f.draw)
          return [
            b.focus > 0 && b.hand.length === 0 ? 7 : -10,
            "Draw a card when placement resources would otherwise go unused.",
          ];
        if (f.damage) {
          const enemy = b.enemies.find((e) => e.uid === a.target);
          const damage = offense(f.damage, f.element, enemy.element);
          return [
            Math.min(damage, enemy.hp) * w.damage +
              (damage >= enemy.hp ? 14 : 0) -
              reserve,
            "Use the flask to finish an enemy or prevent a costly extra turn.",
          ];
        }
        return [-10, "Save the consumable."];
      }
      case "chooseClass":
      case "begin":
      case "continueReward":
        return [10, "Advance the journey."];
      case "startGem":
        return [
          f.defense ? 10 : 4,
          "Imbue the starting Bracelet for passive protection.",
        ];
      case "unequip":
        return [
          -25,
          "Keep equipped gear unless replacing it with better gear.",
        ];
      case "equip": {
        const inst = o.inventory.find((x) => x.uid === a.item),
          old = o.inventory.find((x) => x.uid === o.equipment[a.slot]);
        n =
          this.itemValue(inst, o) -
          this.itemValue(old, o) -
          (Object.values(o.equipment).includes(inst.uid)
            ? this.itemValue(inst, o)
            : 0);
        return [
          n > 0 ? 30 + n : -20,
          `Equip only for a net benefit (${n.toFixed(1)}), counting effects, sockets and curses.`,
        ];
      }
      case "move": {
        const p = { x: a.x, y: a.y };
        const targets = o.field.entities
          .filter((e) => !o.field.leftSupplies?.includes(e.uid))
          .map((e) => {
            let value =
              e.type === "Gold"
                ? e.value * 0.35
                : e.type === "Item"
                  ? items[e.item]?.consumable
                    ? items[e.item].consumable.heal && injured > 0
                      ? Math.min(5, injured) * 3 + 8
                      : this.itemValue({ id: e.item }, o) * 2
                    : 25
                  : e.type === "Event"
                    ? 20
                    : e.type === "Tavern"
                      ? o.gold >= 20
                        ? injured * 0.8 + 12
                        : 2
                      : e.enemy
                        ? enemies[e.enemy].tier === "Archon"
                          ? o.field.round > 18
                            ? 20
                            : -5
                          : enemies[e.enemy].tier === "Eidolon"
                            ? -12
                            : 9
                        : 0;
            if (e.enemy) value -= ((e.count || 1) - 1) * 5;
            const d = dist(p, e),
              old = dist(o.field, e);
            return { e, score: value / (d + 1) + (old - d) * 3 };
          });
        n = targets.length ? Math.max(...targets.map((x) => x.score)) : 0;
        for (const e of o.field.entities.filter((x) => x.enemy)) {
          if (dist(p, e) === 0) {
            n -= ((e.count || 1) - 1) * (o.hp < 30 ? 8 : 3);
            const tier = enemies[e.enemy].tier;
            n -=
              tier === "Eidolon"
                ? 12
                : tier === "Archon" && o.field.round < 18
                  ? 8
                  : 0;
          }
          if (o.hp < 20 && dist(p, e) <= 2) n -= 3;
        }
        n -= dist(p, { x: 5, y: 5 }) * 0.1;
        return [
          n,
          "Move toward useful visible encounters, favoring recovery and avoiding dangerous packs.",
        ];
      }
      case "wait":
        return [-1, "End movement when there is no better destination."];
      case "place": {
        const c = cards[f.card],
          e = c.effects,
          slot = b.grid[a.slot],
          ns = adjacent(a.slot).filter((i) => b.grid[i].length),
          existing = b.grid.flat().filter((x) => x.id === c.id).length;
        const hasOffense = b.grid.some((x) => {
          const t = x.at(-1);
          return (
            t &&
            t.used < cards[t.id].limit &&
            (cards[t.id].effects.damage || cards[t.id].effects.hpDamage)
          );
        });
        n = this.cardValue(c.id, o) * 0.5 + 2;
        if (e.focusPermanent) n += b.turn < 5 ? 12 : 2;
        if (c.growth) n += 8 + ns.length * 3;
        if (e.conduit)
          n +=
            ns.filter((i) => ["blast", "shield"].includes(b.grid[i].at(-1).id))
              .length * 2;
        if (e.growAfterAttack) n += 4 + ns.length * 1.5;
        if (e.damage && !hasOffense) n += 8;
        if (e.shield && existing) n -= 12;
        if (c.condition === "isolated") n += ns.length ? -30 : 4;
        if (c.condition === "corner" && !corner(a.slot)) n -= 30;
        if (
          c.condition &&
          ["Earth", "Fire", "Wind", "Water"].includes(c.condition) &&
          !ns.some((i) => b.grid[i].at(-1).element === c.condition)
        )
          n -= 20;
        if (e.adj) n += ns.length * 2;
        if (e.adjInsight)
          n += ns.filter((i) => !b.grid[i].at(-1).sever).length * 2;
        if (e.matchingDamage || e.matchingShield)
          n +=
            ns.filter(
              (i) => b.grid[i].at(-1).id === c.id && !b.grid[i].at(-1).sever,
            ).length * 2;
        if (c.attune)
          n += ns.some((i) => b.grid[i].at(-1).element !== "Arcane") ? 1 : 0;
        for (const i of ns) {
          const neighbor = b.grid[i].at(-1),
            def = cards[neighbor.id];
          if (def.growth) n += 3;
          else if (
            def.effects.growAfterAttack &&
            neighbor.used < def.limit &&
            neighbor.hp < def.hpCap
          )
            n += 1.5;
        }
        if (slot.length && !c.stack) n -= 50;
        if (
          c.stack === "supersede" &&
          slot.at(-1)?.used < cards[slot.at(-1).id].limit
        )
          n -= 10;
        if (c.stack === "tower" && !slot.length) n -= 6;
        return [
          n * w.development,
          "Develop usable offense, growth, and economy while preserving placement conditions.",
        ];
      }
      case "recall":
        return [
          f.spent && b.grid.filter((x) => x.length).length > 10 ? 3 : -15,
          "Clear exhausted cards only when grid space is scarce.",
        ];
      case "activatePhase":
      case "endTurn":
        return [-1, "Advance after worthwhile actions are used."];
      case "activate": {
        if (f.charging && f.canRelease === false)
          return [
            -2,
            "Preserve Channel: this card lacks enough uses to release.",
          ];
        const target = b.enemies.find((e) => e.uid === a.target);
        const threat = b.enemies.reduce(
          (sum, e) => sum + (e.tell.damage || 0) * (e.tell.hits || 1),
          0,
        );
        const protectedBy =
          b.grid.flat().reduce((sum, c) => sum + (c.ward || 0), 0) +
          b.shields.reduce((sum, p) => sum + p.block, 0) +
          o.bonuses.armor +
          3;
        let damage =
          f.damage || f.chargedDamage || (f.randomDamage && 6.5) || 0;
        if (f.charge > 1) damage /= f.charge;
        if (target) {
          damage = offense(damage, a.element, target.element);
          if (target.resist === a.element) damage = Math.ceil(damage / 2);
          if (target.wisp) damage *= a.element === "Arcane" ? 0.5 : 2;
          if (target.flicker) damage = 0.5;
          if (damage >= target.hp) n += 15;
          damage = Math.min(damage, target.hp);
          if (target.id === "colossus" && a.element === "Chaos") n -= 8;
        }
        if (f.all) damage *= b.enemies.length;
        n +=
          damage * w.damage +
          (target && enemyImmuneTo(target, "burn") ? 0 : (f.burn || 0) * 2) +
          (f.burnAll || (f.chargedBurnAll || 0) / (f.charge || 1)) *
            b.enemies.filter((e) => !enemyImmuneTo(e, "burn")).length *
            2 +
          (target && enemyImmuneTo(target, "poison")
            ? 0
            : (f.poison || 0) * 3) +
          (target && enemyImmuneTo(target, "corrode")
            ? 0
            : (f.corrode || 0) * 5);
        n += (f.channel || 0) > a.costs.channel ? 12 : 0;
        n += (f.focusPermanent || 0) * (b.turn < 7 ? 12 : 4);
        n += (f.insight || 0) * 0.4 + (f.focus || 0) * 1.2;
        n += Math.min(injured, f.heal || 0) * w.survival;
        if (f.cleanse)
          n += Object.values(o.status).reduce((x, y) => x + y, 0) * 2;
        if (f.shield)
          n +=
            Math.min(f.shield, Math.max(0, threat - protectedBy)) * w.survival;
        if (f.ward)
          n += Math.min(f.ward, Math.max(0, threat + 3 - protectedBy));
        if (f.taunt) n += o.hp < 15 ? 6 : 0;
        if (f.relief) n += b.turn > b.relief ? 5 : -10;
        if (f.unbind)
          n +=
            b.grid.flat().filter((x) => x.lock || x.sever || x.freeze).length *
            4;
        if (f.allyHeal) n += 4;
        if (f.conduit) {
          const c = b.grid[a.slot].at(-1);
          const supported =
            b.channel > a.costs.channel
              ? adjacent(a.slot).filter((i) => {
                  const x = b.grid[i].at(-1);
                  return (
                    x &&
                    !c.sever &&
                    !x.sever &&
                    ["blast", "shield"].includes(x.id) &&
                    x.used < cards[x.id].limit &&
                    x.lastActivatedTurn !== b.turn
                  );
                }).length
              : 0;
          const protection = b.enemies.reduce((sum, e) => {
            const hit = { damage: e.tell.damage || 0, element: e.tell.element };
            return (
              sum +
              allyHit(hit, c.element, c.hp).remaining -
              allyHit(hit, a.element, c.hp).remaining
            );
          }, 0);
          n += (supported ? 4 + supported : -2) + protection * w.survival;
        }
        if (f.growAfterAttack && target && !target.flicker)
          n += activationGrowth(b, b.grid[a.slot].at(-1), a.slot) * 0.6;
        if (f.magnify) n += 3;
        if (f.shift || f.transmute) n -= 4;
        return [
          n,
          "Balance immediate kills, incoming damage, healing, and future resources.",
        ];
      }
      case "ward":
        return [
          Math.min(f.ward, b.reaction.damage) * w.survival + (f.column + 1) * 2,
          "Absorb damage while preserving defenders closer to the player.",
        ];
      case "block":
      case "bracelet":
        return [
          Math.min(
            b.reaction.damage,
            f.block * defenseRate(f.element, b.reaction.element),
          ) *
            w.survival +
            ((f.column ?? -1) + 1) * 2,
          "Use the portion with the strongest effective Guard against this element.",
        ];
      case "armor":
        return [
          Math.min(b.reaction.damage, f.reflect ? b.reaction.damage : f.armor) *
            w.survival,
          "Choose armor protection for this hit, or preserve reflection by skipping it.",
        ];
      case "intercept": {
        const c = b.grid[a.slot].at(-1),
          d = cards[c.id],
          result = allyHit(b.reaction, defensiveElement(b, c), c.hp, f.swallow);
        return [
          (b.reaction.damage - result.remaining) * w.survival -
            (d.growth || (d.effects.growAfterAttack && c.used < d.limit)
              ? 8
              : 0) -
            (d.effects.heal ? 5 : 0) +
            (f.swallow ? b.reaction.damage : 0) +
            ((f.column ?? 0) + 1) * 2,
          "Protect player HP while retaining valuable growing Allies when possible.",
        ];
      }
      case "skipEquipment":
        return [
          -b.reaction.damage * w.survival,
          "Preserve item Guard by accepting the remaining hit; prefer absorbing damage when possible.",
        ];
      case "takeHit":
        return [
          b.bracelets.reduce((n, p) => n + p.block, 0) +
            o.bonuses.armor -
            (o.hp < 20 ? 10 : 0),
          "Pass grid defenders and choose equipment protection.",
        ];
      case "rewardCard":
        return [
          this.cardValue(a.id, o) - (o.deck.length > 20 ? 6 : 0),
          "Choose a card by its damage, defense, economy, and growth features.",
        ];
      case "usePickup":
        return [
          Math.min(injured, f.heal) * w.survival + 8,
          "Drink visible healing now when injured, without needing a Satchel slot.",
        ];
      case "leaveItem":
        return [0, "Leave an unwanted item without accepting its effects."];
      case "skipReward":
        return [0, "Skip a card that would dilute the deck."];
      case "rewardGem":
      case "rewardSetting":
        return [
          this.gearValue(f.gear, o),
          "Prefer permanent economy and passive protection.",
        ];
      case "takeItem":
      case "buy": {
        const id = f.item,
          d = id?.startsWith("card:") ? null : items[id];
        n = d
          ? this.itemValue({ id }, o) + (d.slot === "gem" ? 3 : 0)
          : this.cardValue(id?.slice(5), o);
        if (a.type === "buy") n -= a.price * 0.13;
        if (o.satchel?.used >= o.satchel?.capacity && d) {
          const loose = o.inventory.filter(
            (x) =>
              !Object.values(o.equipment).includes(x.uid) &&
              !o.inventory.some((g) => g.gem === x.uid) &&
              !items[x.id].cursed,
          );
          if (loose.length)
            n -= Math.min(...loose.map((x) => this.itemValue(x, o)));
        }
        return [
          n,
          "Value the offered item against its price, Satchel space and risk.",
        ];
      }
      case "heal":
        return [injured * 0.9, "Recover HP before the next encounter."];
      case "eventChoice":
        return [
          (f.heal ? Math.min(injured, f.heal) * 1.4 : 0) +
            (f.gold || 0) * 0.2 +
            (f.hp || 0) * 1.5 +
            (f.card ? this.cardValue(f.card, o) : 0) +
            (f.hex ? -30 : 0) +
            (f.item ? this.itemValue({ id: f.item }, o) : 0) +
            (f.clean || f.cleanHex
              ? o.deck.filter((x) => cards[x.id].type === "Hex").length * 20
              : 0) -
            (a.costs.gold || 0) * 0.2 -
            (a.tradeItem != null
              ? this.itemValue(
                  o.inventory.find((x) => x.uid === a.tradeItem),
                  o,
                )
              : 0) -
            (a.tradeCard != null
              ? this.cardValue(o.deck.find((x) => x.uid === a.tradeCard).id, o)
              : 0),
          "Compare the visible reward with the cost of the specific offered item or card.",
        ];
      case "socket": {
        const inst = o.inventory.find((x) => x.uid === a.uid),
          old = o.inventory.find((x) => x.uid === inst.gem),
          g = o.inventory.find((x) => x.uid === a.gem);
        return [
          this.itemValue({ ...inst, gem: g.uid }, o) -
            this.itemValue(inst, o) +
            (g.id === "curseGem" ? 6 : 0) -
            (old?.id === "curseGem" ? 6 : 0) +
            (old ? -10 : 10),
          "Socket unused Gems to activate their powers.",
        ];
      }
      case "upgrade":
        return [
          8 - (a.costs.gold || 0) * 0.06 - (a.costs.hp || 0) * 0.7,
          "Improve a card when the cost is affordable.",
        ];
      case "removeHex": {
        const lostCard = o.deck.find((c) => c.uid === a.sacrificeCard);
        const lostItem = o.inventory.find((x) => x.uid === a.sacrificeItem);
        const hpCost = a.costs.hp || 0;
        return [
          25 -
            hpCost * (o.hp < 25 ? 2 : 0.8) -
            (a.costs.gold || 0) * 0.06 -
            (lostCard ? this.cardValue(lostCard.id, o) : 0) -
            (lostItem ? this.itemValue(lostItem, o) : 0),
          "Weigh Hex relief against the displayed HP, Gold, or sacrifice cost.",
        ];
      }
      case "sell":
        return [
          f.cursed ? 10 : -30,
          "Keep useful equipment; pay to remove a Curse.",
        ];
      case "gossip":
        return [
          !o.archon && o.gold > 100 ? 2 : -5,
          "Buy Archon information only with surplus Gold.",
        ];
      case "leave":
        return [0, "Continue when useful services are exhausted."];
      case "replaceArmor":
        return [
          this.gearValue(f.gear, o) -
            this.itemValue(
              o.inventory.find((x) => x.uid === a.old),
              o,
            ),
          "Replace Armor only for a better evaluated effect.",
        ];
      case "declineArmor":
        return [0, "Respect the three-Armor carry limit."];
      case "remove":
      case "unsocket":
        return [-20, "Avoid unnecessary deck removal or socket churn."];
      default:
        return [
          Object.values(f)
            .filter((x) => typeof x === "number")
            .reduce((a, b) => a + b, 0) * 0.01,
          "Fallback: choose a legal action using available public effects.",
        ];
    }
  }
}

sources.death.mjs:
import { enemies, enemyDeathLines } from "./content.mjs";
const statusNames = { burn: "burning", poison: "poison", corrode: "corrosion" };
const closing = "Another traveler may find a different way.";
// Capture the actual lethal hit before reaction/status cleanup. Do not guess an
// enemy from an attack name: several enemies can share a move name.
export function describeDeath(state, cause = "", hit = null) {
  const enemy =
    !hit?.statusHit && hit?.source != null
      ? state.battle?.enemies.find((e) => e.uid === hit.source)
      : null;
  let detail;
  if (hit?.statusHit || (!hit && statusNames[cause])) {
    const status = hit?.name || cause;
    detail = {
      kind: "status",
      status,
      summary: `You died from ${statusNames[status] || status || "an ongoing status"}.`,
    };
  } else if (enemy) {
    const tier = enemy.tier || enemies[enemy.id]?.tier;
    detail = {
      kind: "enemy",
      enemyId: enemy.id,
      enemyUid: enemy.uid,
      enemyName: enemy.name,
      tier,
      attack: hit.name || cause || "an attack",
      flavor: ["Archon", "Eidolon"].includes(tier)
        ? enemyDeathLines[enemy.id] || ""
        : "",
    };
    detail.summary = `${detail.enemyName} killed you with ${detail.attack}.`;
  } else {
    detail = {
      kind:
        state.mode === "event"
          ? "event"
          : cause === "Burning Itch"
            ? "hex"
            : "other",
      cause,
      summary: cause
        ? `You died ${state.mode === "event" ? "during" : "from"} ${cause}.`
        : "Your journey ended here.",
    };
  }
  return {
    ...detail,
    message: [detail.flavor, detail.summary, closing].filter(Boolean).join(" "),
  };
}
export const deathSummary = (result) =>
  result.death?.summary || describeDeath({}, result.cause).summary;
export const deathMessage = (result) =>
  result.death?.message || describeDeath({}, result.cause).message;

