) => action(id, "Let the enemy act", text, { type: "endTurn" });
const defend = (id, type, slot, text) =>
  action(id, "Choose your defense", text, {
    type,
    ...(slot == null ? {} : { slot }),
  });
const move = (id, x, y, text) =>
